insert into public.pagini (slug, titlu, seo) values ('acasa', 'Acasă', $j${"titlu": "Cantus Mundi – Un cor în fiecare școală", "descriere": "Programul național Cantus Mundi: coruri de copii și tineri în școli și comunități, coordonat de Corul Național de Cameră Madrigal."}$j$::jsonb) on conflict (slug) do update set titlu = excluded.titlu, seo = excluded.seo, actualizat_la = now();
insert into public.blocuri_pagina (pagina_id, pozitie, tip, date) select id, 1, 'hero', $j${"eyebrow": "Programul Național", "titlu": "Cantus\nMundi", "subtitlu": "Un cor în fiecare școală.", "text": "Prin cânt coral, copiii și tinerii învață să se asculte, să colaboreze și să facă parte dintr-o comunitate, indiferent de mediul din care provin.", "buton": {"text": "Alătură-te comunității", "href": "/cont/nou"}, "link": {"text": "Descoperă activitățile", "href": "/programe"}, "imagine_url": "https://madrigal.ro/wp-content/uploads/2026/09/madrigal-photo-e807cb1071a242578cc9-1024x683.webp", "credit": "Cantus Mundi — Ora Copiilor"}$j$::jsonb from public.pagini where slug = 'acasa';
insert into public.blocuri_pagina (pagina_id, pozitie, tip, date) select id, 2, 'cifre', $j${"elemente": [{"valoare": "87.850", "eticheta": "copii"}, {"valoare": "18.042", "eticheta": "dirijori"}, {"valoare": "2.510", "eticheta": "coruri"}, {"valoare": "996", "eticheta": "școli"}, {"valoare": "6.464", "eticheta": "evenimente"}], "nota": "Cifre calculate automat din platformă · exemplu la 14 septembrie 2026"}$j$::jsonb from public.pagini where slug = 'acasa';
insert into public.blocuri_pagina (pagina_id, pozitie, tip, date) select id, 3, 'text_mare', $j${"eyebrow": "Viziune", "titlu": "Muzica îi aduce împreună.", "text": "Inițiativa dirijorului Ion Marin a prins contur în 2011, cu sprijinul membrilor Corului Național de Cameră „Madrigal – Marin Constantin”. În 2014, Cantus Mundi a devenit program național.\n\nMisiunea sa este integrarea socială prin muzică: acces la educație culturală pentru copii și tineri, formarea celor care îi îndrumă și crearea de coruri în școli și comunități.", "link": {"text": "Misiunea și istoria programului", "href": "/despre"}, "fundal": "accent"}$j$::jsonb from public.pagini where slug = 'acasa';
insert into public.blocuri_pagina (pagina_id, pozitie, tip, date) select id, 4, 'carduri', $j${"eyebrow": "Coruri, ateliere și întâlniri", "titlu": "Cum poți participa", "link": {"text": "Toate activitățile", "href": "/programe"}, "fundal": "none", "elemente": [{"pictograma": "♪", "titlu": "Copii și tineri", "text": "Coruri, percuție, ateliere gratuite, școli de vară și tabere. Primii pași în muzică, alături de alți copii și de formatorii Cantus Mundi.", "link": {"text": "Coruri și audiții", "href": "/programe"}}, {"pictograma": "♬", "titlu": "Dirijori și profesori", "text": "Ateliere de dirijat coral și management de cor, formare cu specialiștii Madrigal și resurse pentru lucrul cu un cor de copii.", "link": {"text": "Academia de Dirijat Coral", "href": "/programe"}}, {"pictograma": "↗", "titlu": "Școli și comunități", "text": "Înființarea de coruri, întâlniri între ansambluri, gale, festivaluri și turnee. Ocazii de a învăța și de a urca împreună pe scenă.", "link": {"text": "Programe și evenimente", "href": "/evenimente"}}]}$j$::jsonb from public.pagini where slug = 'acasa';
insert into public.blocuri_pagina (pagina_id, pozitie, tip, date) select id, 5, 'evenimente', $j${"eyebrow": "Calendar", "titlu": "Evenimente apropiate", "link": {"text": "Tot calendarul", "href": "/evenimente"}, "numar": 3, "nota": "Evenimentele se preiau din Hub-ul Madrigal și se publică din panou. Datele afișate sunt exemple.", "gol": "Momentan nu sunt evenimente publicate."}$j$::jsonb from public.pagini where slug = 'acasa';
insert into public.blocuri_pagina (pagina_id, pozitie, tip, date) select id, 6, 'noutati', $j${"eyebrow": "Din activitatea Cantus Mundi", "titlu": "Pe scenă și în comunitate", "link": {"text": "Noutăți Cantus Mundi", "href": "/noutati"}, "numar": 3, "gol": "Momentan nu sunt noutăți publicate."}$j$::jsonb from public.pagini where slug = 'acasa';
insert into public.blocuri_pagina (pagina_id, pozitie, tip, date) select id, 7, 'sprijin', $j${"eyebrow": "Susține Cantus Mundi", "titlu": "Ce face posibil sprijinul tău.", "intro_titlu": "Activități concrete, costuri explicate.", "intro_text": "Sumele sunt orientative și arată cât costă activitățile pe care le poți susține. Nu trebuie să acoperi întreaga sumă: donația ta se adaugă celorlalte contribuții.", "numar": "01", "categorie": "Educație prin muzică", "titlu_card": "Un cor în\nCantus Mundi", "text_card": "Sprijină muzica în viața unui cor de aproximativ 30 de copii: îndrumarea unui dirijor, costume și experiențe împreună.", "buton": {"text": "Contribuie la acest proiect", "href": "https://madrigal.ro/"}, "imagine_url": "https://madrigal.ro/wp-content/uploads/2026/09/madrigal-photo-9fc853ada3101ca3df2a-768x512.webp", "concret_titlu": "Ce înseamnă, concret", "sume": [{"text": "Un dirijor pentru un cor de aproximativ 30 de copii, timp de un an", "valoare": "18.000 lei"}, {"text": "Un costum pentru un copil", "valoare": "500 lei"}, {"text": "O deplasare de o zi a copiilor cu autocarul", "valoare": "4.500 lei"}], "nota": "Plata se face prin procesatorul instituției (de stabilit)."}$j$::jsonb from public.pagini where slug = 'acasa';
insert into public.blocuri_pagina (pagina_id, pozitie, tip, date) select id, 8, 'cta', $j${"eyebrow": "Platforma Cantus Mundi", "titlu": "Găsește-ți locul în comunitate.", "text": "Înscrieri, coruri, resurse de învățare și informații despre activități, într-un singur cont.", "fundal": "peach", "butoane": [{"text": "Intră în platformă", "href": "/cont", "stil": "primary"}, {"text": "Creează cont de dirijor", "href": "/cont/nou", "stil": "outline"}], "link": {"text": "Voluntariat", "href": "/implica-te"}}$j$::jsonb from public.pagini where slug = 'acasa';
insert into public.blocuri_pagina (pagina_id, pozitie, tip, date) select id, 9, 'galerii', $j${"titlu": "În imagini", "nota": "Fotografii din arhiva Madrigal, folosite temporar.", "albume": [{"titlu": "Cantus Mundi — Ora Copiilor", "imagini": ["https://madrigal.ro/wp-content/uploads/2026/09/madrigal-photo-e807cb1071a242578cc9-768x512.webp", "https://madrigal.ro/wp-content/uploads/2026/09/madrigal-photo-9fc853ada3101ca3df2a-768x512.webp"], "link": {"text": "Vezi albumul complet", "href": "/noutati"}}, {"titlu": "Cantus Mundi — Ora Pământului", "imagini": ["https://madrigal.ro/wp-content/uploads/2026/09/madrigal-photo-35dedbe51f015f1e3a07-768x512.webp", "https://madrigal.ro/wp-content/uploads/2026/09/madrigal-photo-e07e8e1dab811bfe5973-768x512.webp"], "link": {"text": "Vezi albumul complet", "href": "/noutati"}}, {"titlu": "Cantus Mundi — Academia de Dirijat", "imagini": ["https://madrigal.ro/wp-content/uploads/2026/09/madrigal-photo-ce588a043301c940d5c9-768x512.webp", "https://madrigal.ro/wp-content/uploads/2026/09/madrigal-photo-32f8532de1fa4adf89a8-768x512.webp"], "link": {"text": "Vezi albumul complet", "href": "/noutati"}}, {"titlu": "Cantus Mundi — Forum", "imagini": ["https://madrigal.ro/wp-content/uploads/2026/09/madrigal-photo-b70b96f384efd9c80d45-768x512.webp", "https://madrigal.ro/wp-content/uploads/2026/09/madrigal-photo-6b20c97e1e14789fb1ef-768x512.webp"], "link": {"text": "Vezi albumul complet", "href": "/noutati"}}]}$j$::jsonb from public.pagini where slug = 'acasa';
