insert into public.blocuri_pagina (pagina_id, pozitie, tip, date) select id, 3, 'cta', $j${"eyebrow": "Platforma Cantus Mundi", "titlu": "Găsește-ți locul în comunitate.", "text": "Înscrieri, coruri, resurse de învățare și informații despre activități, într-un singur cont.", "fundal": "peach", "butoane": [{"text": "Intră în platformă", "href": "/cont", "stil": "primary"}, {"text": "Creează cont de dirijor", "href": "/cont/nou", "stil": "outline"}], "link": {"text": "Voluntariat", "href": "/implica-te"}}$j$::jsonb from public.pagini where slug = 'implica-te';
insert into public.pagini (slug, titlu, seo) values ('sustine', 'Susține', $j${"titlu": "Susține Cantus Mundi", "descriere": "Sprijină muzica în viața copiilor."}$j$::jsonb) on conflict (slug) do update set titlu = excluded.titlu, seo = excluded.seo, actualizat_la = now();
insert into public.blocuri_pagina (pagina_id, pozitie, tip, date) select id, 1, 'hero_pagina', $j${"eyebrow": "Susține", "titlu": "Susține Cantus Mundi", "text": "Activități concrete, costuri explicate."}$j$::jsonb from public.pagini where slug = 'sustine';
insert into public.blocuri_pagina (pagina_id, pozitie, tip, date) select id, 2, 'sprijin', $j${"eyebrow": "Susține Cantus Mundi", "titlu": "Ce face posibil sprijinul tău.", "intro_titlu": "Activități concrete, costuri explicate.", "intro_text": "Sumele sunt orientative și arată cât costă activitățile pe care le poți susține. Nu trebuie să acoperi întreaga sumă: donația ta se adaugă celorlalte contribuții.", "numar": "01", "categorie": "Educație prin muzică", "titlu_card": "Un cor în\nCantus Mundi", "text_card": "Sprijină muzica în viața unui cor de aproximativ 30 de copii: îndrumarea unui dirijor, costume și experiențe împreună.", "buton": {"text": "Contribuie la acest proiect", "href": "https://madrigal.ro/"}, "imagine_url": "https://madrigal.ro/wp-content/uploads/2026/09/madrigal-photo-9fc853ada3101ca3df2a-768x512.webp", "concret_titlu": "Ce înseamnă, concret", "sume": [{"text": "Un dirijor pentru un cor de aproximativ 30 de copii, timp de un an", "valoare": "18.000 lei"}, {"text": "Un costum pentru un copil", "valoare": "500 lei"}, {"text": "O deplasare de o zi a copiilor cu autocarul", "valoare": "4.500 lei"}], "nota": "Plata se face prin procesatorul instituției (de stabilit)."}$j$::jsonb from public.pagini where slug = 'sustine';
insert into public.pagini (slug, titlu, seo) values ('contact', 'Contact', $j${"titlu": "Contact", "descriere": "Scrie echipei Cantus Mundi."}$j$::jsonb) on conflict (slug) do update set titlu = excluded.titlu, seo = excluded.seo, actualizat_la = now();
